def expand_simple(grid):
    """Simpler expand: non-1 values create 3x3 blocks, no overlap handling"""
    result = [[0]*len(grid[0]) for _ in range(len(grid))]
    h, w = len(grid), len(grid[0])

    # Create mask of which cells to expand
    mask = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                # Mark all cells in 3x3 block centered at (r,c)
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w:
                            mask.add((rr, cc))

    # Assign values (higher wins if there's conflict, original wins in center)
    for r in range(h):
        for c in range(w):
            if (r, c) in mask:
                # Find all non-1 values that claim this cell
                values = []
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w:
                            if grid[rr][cc] == grid[r][c] and grid[r][c] >= 2:
                                values.append(grid[r][c])
                        if grid[rr][cc] >= 2:
                            if (rr, cc) == (r, c):  # Only count once
                                pass
                # Higher priority value (larger) wins
                if values:
                    result[r][c] = max(values)
    return result

