# Apply transform: marker V at (r, c) creates 3x3 block at output centered at (r-1, c)
# 3x3: rows r-2 to r (inclusive), cols c-1 to c+1 (inclusive)
def apply_transform(grid):
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]
    h_out, w_out = len(grid), len(grid[0])
    markers = []

    for r in range(h_out):
        for c in range(w_out):
            if grid[r][c] >= 2:
                markers.append((grid[r][c], r, c))

    for r in range(h_out):
        for c in range(w_out):
            claiming = []
            for v, mr, mc in markers:
                # Marker (mr, mc) covers output rows mr-2 to mr, cols mc-1 to mc+1
                if mr - 2 <= r <= mr and mc - 1 <= c <= mc + 1:
                    claiming.append(v)

            if claiming:
                result[r][c] = max(claiming)
            elif grid[r][c] == 1:
                result[r][c] = grid[r][c]

    return result

