                while stack:
                    cr, cc = stack.pop()
                    region_cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] >= 1:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                all_regions.append(region_cells)

    # For each region, find marker (cell with value >= 2), create 3x3 block
    output = [[0]*w for _ in range(h)]
